"""Index and display correction checks already generated by the shared adapter."""

import base64
import html
import json
from pathlib import Path

import nibabel as nib
import numpy as np

from .acquisition_metadata import entities
from .execution import _publish_json, hash_file
from .qc import artifact, load_catalog
from .qc_figures import native_montages


def _motion_plot(directory: Path, gate: dict) -> Path:
    """Plot saved motion and detection counts with real volume indices, no grading."""
    movement = np.asarray(gate["movement_rms"])
    counts = np.zeros(len(movement), int)
    for volume, _ in gate["detected_pairs"]:
        counts[volume] += 1
    width, height = 1000, 560
    parts = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}">',
        f'<rect width="{width}" height="{height}" fill="#101821"/>',
        '<g fill="#e7edf5" font-family="sans-serif" font-size="15">',
        '<text x="20" y="25">Saved EDDY metrics · scientific review required</text>',
    ]
    for row, (label, series) in enumerate(
        [
            ("Motion RMS (mm): blue absolute, gold relative", [movement[:, 0], movement[:, 1]]),
            (
                "Detected outlier slices per volume (not a measure of replacement fidelity)",
                [counts],
            ),
        ]
    ):
        y0 = 65 + row * 245
        maximum = max(float(np.max(v)) for v in series)
        scale = maximum if maximum > 0 else 1.0
        parts += [
            f'<text x="20" y="{y0 - 15}">{label}</text>',
            f'<text x="12" y="{y0 + 12}">{maximum:.4g}</text>',
            f'<text x="32" y="{y0 + 180}">0</text>',
            f'<path d="M75 {y0}V{y0 + 180}H970" fill="none" stroke="#a0acba"/>',
        ]
        for values, color in zip(series, ["#71a7ff", "#ffcf70"], strict=False):
            coords = [
                (75 + 895 * v / max(1, len(values) - 1), y0 + 180 - 180 * float(value) / scale)
                for v, value in enumerate(values)
            ]
            points = " ".join(f"{x:.3f},{y:.3f}" for x, y in coords)
            parts.append(
                f'<polyline points="{points}" fill="none" stroke="{color}" stroke-width="2"/>'
            )
        for v in sorted({0, len(movement) // 2, len(movement) - 1}):
            x = 75 + 895 * v / max(1, len(movement) - 1)
            parts.append(f'<text x="{x - 8}" y="{y0 + 202}">{v}</text>')
        parts.append(f'<text x="390" y="{y0 + 225}">Original volume index (zero-based)</text>')
    parts.append("</g></svg>")
    path = directory / "diagnostic-motion-outliers.svg"
    with path.open("x") as stream:
        stream.write("\n".join(parts))
    return path


def _range(values) -> tuple[float, float]:
    """Choose one fixed display range per array, retaining invalid-pixel marking."""
    selected = np.asarray(values)
    selected = selected[np.isfinite(selected) & (selected != 0)]
    low, high = np.percentile(selected, [0.5, 99.5]) if selected.size else (0, 1)
    return float(low), float(high if high > low else low + 1)


def export_correction_catalog(
    dataset, folder: Path, manifest: dict, *, report_directory: Path | None = None
) -> Path:
    """Export portable completed/failed evidence without launching any MRI tools."""
    p = manifest["plan"]
    report_directory = report_directory or folder
    if report_directory != folder:
        report_directory.mkdir(exist_ok=False)
        _publish_json(report_directory / "correction-manifest.json", manifest)
        if "correction_gate" in manifest["validation"]:
            _publish_json(
                report_directory / "correction-gate.json", manifest["validation"]["correction_gate"]
            )
    figures, stages = [], []
    correction = folder / "correction"
    gate = manifest["validation"].get("correction_gate")
    figures_directory = report_directory / "qc-figures"
    if "topup" in manifest["validation"]:
        before = nib.load(correction / "b0-pairs.nii")
        after = nib.load(correction / "unwarped.nii.gz")
        # Calibration-specific views prevent hiding a misassociated reference
        # behind an across-calibration average.
        for v in range(before.shape[3]):
            a, b = (np.asarray(image.dataobj[..., v]) for image in (before, after))
            window = _range(a)
            figures += native_montages(
                dataset,
                [
                    {"array": a, "title": "Before TOPUP", "range": window},
                    {"array": b, "title": "After TOPUP", "range": window},
                ],
                figures_directory,
                f"topup-calibration-{v:03d}",
            )
    if "mask" in manifest["validation"]:
        corrected = nib.load(correction / "eddy.nii.gz")
        before = nib.load(correction / "input.nii")
        indices = p["shells"][0]["indices"]
        means = [
            sum(np.asarray(image.dataobj[..., v], np.float64) / len(indices) for v in indices)
            for image in (before, corrected)
        ]
        mask = np.asarray(nib.load(folder / "evaluation/mask.nii.gz").dataobj)
        fitting = np.asarray(nib.load(correction / "fitting_mask.nii.gz").dataobj)
        window = _range(means[0][mask > 0])
        figures += native_montages(
            dataset,
            [
                {"array": means[0], "title": "Before correction", "range": window},
                {"array": means[1], "title": "After correction", "range": window},
                {"array": means[1], "title": "dwi2mask outline", "range": window, "mask": mask},
                {
                    "array": means[1],
                    "title": "BET fitting outline",
                    "range": window,
                    "mask": fitting,
                },
            ],
            figures_directory,
            "eddy-mean-low-b-mask",
        )
    if gate:
        figures_directory.mkdir(exist_ok=True)
        figures.append(_motion_plot(figures_directory, gate))
        cnr = nib.load(correction / "eddy.eddy_cnr_maps.nii.gz")
        for channel, shell in enumerate(p["shells"]):
            values = np.asarray(cnr.dataobj[..., channel])
            figures += native_montages(
                dataset,
                [
                    {
                        "array": values,
                        "title": f"{'SNR' if channel == 0 else 'CNR'} b~{shell['mean_bvalue']:.0f}",
                        "range": _range(values),
                        "colormap": "viridis",
                    }
                ],
                figures_directory,
                f"diagnostic-channel-{channel}",
            )
    report = report_directory / "correction-QC.html"
    embedded = "".join(
        f'<figure><figcaption>{html.escape(path.stem)}</figcaption><img src="data:image/svg+xml;base64,{base64.b64encode(path.read_bytes()).decode()}" alt="{html.escape(path.stem)}"></figure>'
        for path in figures
    )
    logs = "".join(
        f"<details><summary>{html.escape(path.name)}</summary><pre>{html.escape(path.read_text(errors='replace'))}</pre></details>"
        for path in sorted((folder / "logs").glob("*.log"))
    )
    text = f"""<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>TOPUP/EDDY correction QC</title><style>body{{font:16px system-ui;background:#101821;color:#e7edf5;margin:28px;line-height:1.5}}img{{max-width:100%;height:auto}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;background:#1a2532;padding:16px}}summary{{cursor:pointer}}</style>
<h1>TOPUP/EDDY correction QC</h1><p>Execution/verification result: {html.escape(manifest["status"])}. <strong>Scientific review required.</strong></p>
<p>{html.escape(manifest.get("error", "No technical error recorded. This does not establish anatomical or scientific acceptance."))}</p>
<p>Source: {html.escape(str(dataset.paths.dwi))}. All {dataset.n_volumes} acquired volumes retain their order on the native diffusion grid. Rotated vectors belong to the corrected images. N4, T1 alignment and AP/PA combination are not performed by this operation.</p>
<p>Before/after differences include correction interpolation and motion; they are not noise-only residuals. CNR and inclusive prediction residuals are fitted diagnostics, not independent ground truth. Mask contours are candidates for anatomical review. This report has no automatically completed visual review.</p>
<details open><summary>Checks and shell diagnostics</summary><pre>{html.escape(json.dumps(manifest["validation"], indent=2))}</pre></details>
<details><summary>Acquisition evidence, actual commands and versions</summary><pre>{html.escape(json.dumps(p, indent=2))}</pre></details>
{embedded}{logs}</html>"""
    with report.open("x") as stream:
        stream.write(text)
    if 'src="http' in text or "<script" in text or 'href="file:' in text:
        raise ValueError("External visual dependency in portable correction report")
    common = [
        artifact(report, "report", "Portable correction QC, including failures and pending review"),
        artifact(
            report_directory / "correction-manifest.json",
            "history",
            "Frozen commands, execution and verification",
        ),
    ]
    for name in ("topup", "eddy", "final_mask"):
        step = next((s for s in manifest["steps"] if s["step"] == name), None)
        ran = step is not None and step.get("return_code") == 0
        passed = {"topup": "topup", "eddy": "eddy_integrity", "final_mask": "mask"}[
            name
        ] in manifest["validation"]
        artifacts = list(common)
        log = folder / "logs" / f"{name}.log"
        if log.is_file():
            artifacts.append(artifact(log, "log", f"{name} execution log"))
        matching = [
            f
            for f in figures
            if f.name.startswith(
                "topup" if name == "topup" else "eddy" if name == "final_mask" else "diagnostic"
            )
        ]
        artifacts.extend(artifact(f, "figure", f.stem) for f in matching)
        findings = ["Scientific review pending; no automatic anatomical acceptance."]
        if name == "eddy" and gate:
            artifacts.append(
                artifact(
                    report_directory / "correction-gate.json",
                    "metrics",
                    "Saved shell/volume prediction, motion and outlier checks",
                )
            )
            findings.extend(gate["flags"] + gate["scientific_concerns"])
        stages.append(
            {
                "id": name,
                "title": {
                    "topup": "Susceptibility correction",
                    "eddy": "EDDY motion and eddy-current correction",
                    "final_mask": "Final brain mask candidate",
                }[name],
                "execution": "completed" if ran else "failed" if step else "pending",
                "technical": "passed" if passed else "failed" if step else "pending",
                "automated_qc": ("passed" if gate["technical_checks_passed"] else "failed")
                if name == "eddy" and gate
                else "pending",
                "scientific_review": "required",
                "findings": findings,
                "artifacts": artifacts,
            }
        )
    if "eddy_integrity" in manifest["validation"]:
        sources = {
            "before": {
                "dwi": str(correction / "input.nii"),
                "bval": str(folder / "inputs.bvals"),
                "bvec": str(folder / "inputs.bvecs"),
            },
            "after": {
                "dwi": str(correction / "eddy.nii.gz"),
                "bval": str(correction / "corrected.bval"),
                "bvec": str(correction / "corrected.bvec"),
            },
        }
        replacement = correction / "eddy.eddy_outlier_free_data.nii.gz"
        if replacement.is_file():
            sources["replaced_original_grid"] = {
                "dwi": str(replacement),
                "bval": str(folder / "inputs.bvals"),
                "bvec": str(folder / "inputs.bvecs"),
            }
        for source in sources.values():
            source["sha256"] = {k: hash_file(Path(v)) for k, v in source.items()}
        comparison = report_directory / "correction-comparison.json"
        modes = [
            {
                "label": "Before / after EDDY",
                "left": "before",
                "right": "after",
                "pairs": [[v, v] for v in range(dataset.n_volumes)],
                "description": "All volumes in acquired order; spatial correction and gradient rotation are expected changes",
            }
        ]
        if "replaced_original_grid" in sources:
            modes.append(
                {
                    "label": "Original / outlier-replaced acquisition grid",
                    "left": "before",
                    "right": "replaced_original_grid",
                    "pairs": [[v, v] for v in range(dataset.n_volumes)],
                    "description": "EDDY's saved outlier-free data in the acquisition grid; original unrotated gradients. Inspect replacement locations and signal changes separately from motion-corrected output.",
                }
            )
        _publish_json(
            comparison,
            {
                "notice": "Native-grid before/after correction; matching volume identities, rotated gradients and interpolation differences. Scientific review pending.",
                "sources": sources,
                "modes": modes,
            },
        )
        stages[1]["artifacts"].append(
            artifact(comparison, "comparison", "All-volume corrected-image comparison")
        )
    for name in ("bias", "alignment"):
        stages.append(
            {
                "id": name,
                "title": "N4 bias correction" if name == "bias" else "T1 alignment",
                "execution": "pending",
                "technical": "pending",
                "automated_qc": "pending",
                "scientific_review": "required",
                "findings": [
                    "Separate operation; requires passing upstream evidence and explicit inputs."
                ],
                "artifacts": [],
            }
        )
    destination = report_directory / "qc-catalog.json"
    labels, _ = entities(Path(p["acquisition"]["image"]))
    _publish_json(
        destination,
        {
            "schema_version": 1,
            "kind": "dmri_qc_catalog",
            "identity": {
                "subject": "sub-" + labels["sub"],
                "session": "ses-" + labels["ses"] if "ses" in labels else "not specified",
                "acquisition": labels.get("acq", "DWI"),
            },
            "stages": stages,
        },
    )
    load_catalog(destination)
    return destination
